{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _view(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": name,
            "owes": dict(sorted(user["owes"].items())),
            "owed_by": dict(sorted(user["owed_by"].items())),
            "balance": balance,
        }

    @staticmethod
    def _load(payload):
        if payload is None or payload == "":
            return {}
        return json.loads(payload) if isinstance(payload, (str, bytes)) else payload

    def get(self, url, payload=None):
        if url == "/users":
            data = self._load(payload)
            names = data.get("users") if data else None
            if names is None:
                names = list(self.users)
            names = sorted(n for n in names if n in self.users)
            return json.dumps({"users": [self._view(n) for n in names]})
        raise ValueError("Unknown URL: " + str(url))

    def post(self, url, payload=None):
        data = self._load(payload)
        if url == "/add":
            name = data["user"]
            if name in self.users:
                raise ValueError("User already exists: " + name)
            self.users[name] = {"owes": {}, "owed_by": {}}
            return json.dumps(self._view(name))
        if url == "/iou":
            lender, borrower, amount = data["lender"], data["borrower"], data["amount"]
            if lender not in self.users or borrower not in self.users:
                raise ValueError("Unknown user")
            if lender == borrower:
                raise ValueError("Lender and borrower must differ")
            lu, bu = self.users[lender], self.users[borrower]
            net = bu["owes"].pop(lender, 0) - bu["owed_by"].pop(borrower if False else lender, 0) + amount
            lu["owed_by"].pop(borrower, None)
            lu["owes"].pop(borrower, None)
            bu["owes"].pop(lender, None)
            if net > 0:
                bu["owes"][lender] = net
                lu["owed_by"][borrower] = net
            elif net < 0:
                bu["owed_by"][lender] = -net
                lu["owes"][borrower] = -net
            return json.dumps({"users": [self._view(n) for n in sorted((lender, borrower))]})
        raise ValueError("Unknown URL: " + str(url))
"}
